export const getTicketComments = (
    id: number,
    params: GetTicketCommentsParams,
 options?: SecondParameter<typeof axiosInstanceFn>,signal?: AbortSignal
) => {
      
      
      return axiosInstanceFn<ApiResponsePageResponseTicketCommentResponseDTO>(
      {url: `/support/tickets/${id}/comments`, method: 'GET',
        params, signal
    },
      options);
    }
  

export const getGetTicketCommentsQueryKey = (id?: number,
    params?: GetTicketCommentsParams,) => {
    return [`/support/tickets/${id}/comments`, ...(params ? [params]: [])] as const;
    }

    
export const getGetTicketCommentsQueryOptions = <TData = Awaited<ReturnType<typeof getTicketComments>>, TError = ErrorType<unknown>>(id: number,
    params: GetTicketCommentsParams, options?: { query?:Partial<UseQueryOptions<Awaited<ReturnType<typeof getTicketComments>>, TError, TData>>, request?: SecondParameter<typeof axiosInstanceFn>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getGetTicketCommentsQueryKey(id,params);

  

    const queryFn: QueryFunction<Awaited<ReturnType<typeof getTicketComments>>> = ({ signal }) => getTicketComments(id,params, requestOptions, signal);

      

      

   return  { queryKey, queryFn, enabled: !!(id), ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof getTicketComments>>, TError, TData> & { queryKey: DataTag<QueryKey, TData, TError> }
}

export type GetTicketCommentsQueryResult = NonNullable<Awaited<ReturnType<typeof getTicketComments>>>
export type GetTicketCommentsQueryError = ErrorType<unknown>


